{"cmd":"python3 - <<'PY'
import csv
import datetime as dt
import requests
from typing import Dict, Any

stations_path='/root/data/michigan_stations.txt'
output_path='/root/output/flood_results.csv'

start_date=dt.date(2025,4,1)
end_date=dt.date(2025,4,7)
# use end_dt_exclusive for iv request
end_dt_exclusive=end_date + dt.timedelta(days=1)

with open(stations_path) as f:
    stations=[line.strip() for line in f if line.strip()]

session=requests.Session()

results=[]

for site in stations:
    # Fetch flood stage
    fs_url=f'https://waterdata.usgs.gov/flood-stage/{site}'
    try:
        fs_resp=session.get(fs_url, timeout=20)
        if fs_resp.status_code!=200:
            continue
        fs_data=fs_resp.json()
    except Exception:
        continue
    if not fs_data or 'stages' not in fs_data:
        continue
    stages=fs_data.get('stages') or {}
    flood_stage=stages.get('minor')
    if flood_stage is None:
        # If minor missing, try 'moderate' or 'action'? treat as not available
        continue
    try:
        flood_stage=float(flood_stage)
    except Exception:
        continue
    param_code=fs_data.get('parameter_code') or '00065'

    iv_url='https://nwis.waterservices.usgs.gov/nwis/iv/'
    params={
        'format':'json',
        'sites':site,
        'startDT':start_date.isoformat(),
        'endDT':end_dt_exclusive.isoformat(),
        'parameterCd':param_code,
    }
    try:
        iv_resp=session.get(iv_url, params=params, timeout=30)
        if iv_resp.status_code!=200:
            continue
        iv_data=iv_resp.json()
    except Exception:
        continue

    ts_list=iv_data.get('value', {}).get('timeSeries', [])
    if not ts_list:
        continue

    flood_days=set()
    for ts in ts_list:
        values=ts.get('values', [])
        if not values:
            continue
        for val in values[0].get('value', []):
            v_str=val.get('value')
            dt_str=val.get('dateTime')
            if v_str is None or dt_str is None:
                continue
            try:
                v=float(v_str)
            except Exception:
                continue
            if v < flood_stage:
                continue
            try:
                d=dt.datetime.fromisoformat(dt_str).date()
            except Exception:
                # fallback: strip timezone
                try:
                    d=dt.datetime.fromisoformat(dt_str[:19]).date()
                except Exception:
                    continue
            if start_date <= d <= end_date:
                flood_days.add(d)
    if flood_days:
        results.append((site, len(flood_days)))

# sort by station id
results.sort(key=lambda x: x[0])

with open(output_path, 'w', newline='') as f:
    writer=csv.writer(f)
    writer.writerow(['station_id','flood_days'])
    writer.writerows(results)

print(f"Wrote {len(results)} stations to {output_path}")
PY"}
